import { getEnv } from "@/env";

/**
 * Public SEO files are generated by Django (it knows the catalogue); Start serves them on
 * the one public origin. Unauthenticated and cookie-free, so it bypasses the `/api/**`
 * session handling. The forwarded host lets Django build absolute URLs for the public origin.
 */
export function seoHandler(path: string) {
  return async ({ request }: { request: Request }) => {
    const incoming = new URL(request.url);
    const headers = new Headers();
    headers.set("x-forwarded-host", request.headers.get("x-forwarded-host") ?? incoming.host);
    headers.set(
      "x-forwarded-proto",
      request.headers.get("x-forwarded-proto") ?? incoming.protocol.slice(0, -1),
    );
    const res = await fetch(new URL(path, getEnv().API_INTERNAL_URL), { headers });
    const out = new Headers();
    out.set("content-type", res.headers.get("content-type") ?? "text/plain; charset=utf-8");
    out.set("cache-control", "public, max-age=3600");
    return new Response(res.body, { status: res.status, headers: out });
  };
}
